package com.hrflow.platform.department;
import com.hrflow.platform.common.ApiModels.*; import com.hrflow.platform.employee.EmployeeRepository; import com.hrflow.platform.exception.ApiException; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class DepartmentService {private final DepartmentRepository repo;private final EmployeeRepository employees;
 @Transactional public DepartmentView create(DepartmentInput in){if(repo.existsByNameIgnoreCase(in.name().trim()))throw ApiException.conflict("Un département porte déjà ce nom");Department d=new Department();apply(d,in);return view(repo.save(d));}
 @Transactional(readOnly=true) public Page<DepartmentView> list(String q,Pageable p){return(q==null||q.isBlank()?repo.findAll(p):repo.findByNameContainingIgnoreCase(q,p)).map(this::view);}
 @Transactional(readOnly=true) public DepartmentView get(Long id){return view(entity(id));}@Transactional public DepartmentView update(Long id,DepartmentInput in){Department d=entity(id);if(repo.existsByNameIgnoreCaseAndIdNot(in.name().trim(),id))throw ApiException.conflict("Un département porte déjà ce nom");apply(d,in);return view(d);}
 @Transactional public DepartmentView status(Long id,StatusUpdate in){Department d=entity(id);if(!in.active()&&employees.countByDepartmentIdAndActiveTrue(id)>0)throw ApiException.conflict("Un département avec des employés actifs ne peut pas être désactivé");d.setActive(in.active());return view(d);} public Department entity(Long id){return repo.findById(id).orElseThrow(()->ApiException.notFound("Département introuvable"));} private void apply(Department d,DepartmentInput i){d.setName(i.name().trim());d.setDescription(i.description());} private DepartmentView view(Department d){return new DepartmentView(d.getId(),d.getName(),d.getDescription(),d.isActive(),d.getCreatedAt(),d.getUpdatedAt());}
}
